findings.codeql_raw_query:
/**
 * @name Untrusted data written to filesystem
 * @description Flags flows from remote-like sources (BeautifulSoup text/attributes) to file write operations in soupsieve.
 * @kind path-problem
 * @problem.severity warning
 * @id py/soupsieve/untrusted-to-file
 * @tags security
 *       external/cwe/cwe-073
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts

module UntrustedToFileConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(FileSystemAccess fa |
      sink = fa.getAPathArgument()
    )
  }
}

module UntrustedToFileFlow = TaintTracking::Global<UntrustedToFileConfig>;
import UntrustedToFileFlow::PathGraph

from UntrustedToFileFlow::PathNode source, UntrustedToFileFlow::PathNode sink
where UntrustedToFileFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Untrusted data from $@ reaches a file path argument.", source.getNode(), "user-controlled"
